<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { adminApi, type AdminOrder } from '@/services/adminApi'

const router = useRouter()
const orders = ref<AdminOrder[]>([])
const selected = ref<AdminOrder | null>(null)
const error = ref('')
const isLoading = ref(true)
const user = ref({ name: '', email: '', password: '', role: 'advisor' })
const userMessage = ref('')
const paidOrders = computed(() => orders.value.filter((order) => order.status === 'paid'))
const salesTotal = computed(() => paidOrders.value.reduce((total, order) => total + order.total, 0))
const formatPrice = (value: number) => `$${value.toFixed(2)}`
const formatDate = (value: string) => new Intl.DateTimeFormat('es-EC', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
const whatsappLink = (phone: string, order: string) => `https://wa.me/${phone.replace(/\D/g, '')}?text=${encodeURIComponent(`Hola, te escribimos de Bruval sobre tu pedido ${order}.`)}`

async function loadOrders() { try { isLoading.value = true; const { data } = await adminApi.orders(); orders.value = data } catch (reason: any) { error.value = reason.message || 'No pudimos cargar las ventas.' } finally { isLoading.value = false } }
async function createUser() { userMessage.value = ''; try { await adminApi.createUser(user.value); userMessage.value = 'Usuario creado correctamente.'; user.value = { name: '', email: '', password: '', role: 'advisor' } } catch (reason: any) { userMessage.value = reason.message || 'No pudimos crear el usuario.' } }
function logout() { localStorage.removeItem('access_token'); localStorage.removeItem('admin_name'); router.replace('/admin/login') }
onMounted(loadOrders)
</script>

<template>
  <main class="dashboard"><header><a href="/" class="brand">bruval<span>.</span></a><div><p>Panel de ventas</p><button type="button" @click="logout">Salir</button></div></header><section class="intro"><p class="eyebrow">Operación · Guayaquil</p><h1>Todo lo que<br><i>está floreciendo.</i></h1><button type="button" @click="loadOrders">Actualizar ventas ↻</button></section><section class="metrics"><div><span>Ventas confirmadas</span><strong>{{ paidOrders.length }}</strong></div><div><span>Total cobrado</span><strong>{{ formatPrice(salesTotal) }}</strong></div><div><span>Por coordinar</span><strong>{{ orders.filter((order) => order.status === 'awaiting_payment').length }}</strong></div></section><p v-if="error" class="error">{{ error }}</p><section class="sales"><div class="section-title"><h2>Órdenes</h2><span>{{ orders.length }} registros</span></div><div v-if="isLoading" class="loading">Cargando ventas...</div><button v-for="order in orders" v-else :key="order._id" class="order-row" type="button" @click="selected = order"><span><b>{{ order.orderNumber }}</b><small>{{ order.customer.name }} · {{ formatDate(order.createdAt) }}</small></span><span><em :class="order.status">{{ order.status === 'paid' ? 'Pagado' : order.status === 'awaiting_payment' ? 'Pendiente' : 'Fallido' }}</em><strong>{{ formatPrice(order.total) }}</strong></span></button></section><section class="create-user"><div><p class="eyebrow">Equipo</p><h2>Crear usuario</h2><p>Agrega asesores o administradores al panel.</p></div><form @submit.prevent="createUser"><input v-model.trim="user.name" required placeholder="Nombre completo"><input v-model.trim="user.email" required type="email" placeholder="correo@bakano.ec"><input v-model="user.password" required minlength="8" type="password" placeholder="Contraseña temporal"><select v-model="user.role"><option value="advisor">Asesor</option><option value="admin">Administrador</option></select><button type="submit">Crear acceso →</button><p v-if="userMessage">{{ userMessage }}</p></form></section><Transition name="fade"><aside v-if="selected" class="detail"><button type="button" class="close" @click="selected = null">×</button><p class="eyebrow">{{ selected.orderNumber }}</p><h2>{{ selected.customer.name }}</h2><p class="contact">{{ selected.customer.email }}<br>{{ selected.customer.phone }}</p><a class="whatsapp" :href="whatsappLink(selected.customer.phone, selected.orderNumber)" target="_blank" rel="noopener">Hablar por WhatsApp ↗</a><div class="detail-block"><strong>Pedido</strong><p v-for="item in selected.items" :key="item.name">{{ item.quantity }} x {{ item.name }} <span>{{ formatPrice(item.price * item.quantity) }}</span></p><b>Total {{ formatPrice(selected.total) }}</b></div><div class="detail-block"><strong>Entrega</strong><p>{{ selected.delivery.recipient }} · {{ selected.delivery.date }}, {{ selected.delivery.timeSlot }}</p><p>{{ selected.delivery.address }}</p><a :href="selected.delivery.mapUrl" target="_blank" rel="noopener">Abrir Google Maps ↗</a><p class="card">“{{ selected.delivery.messageCard }}”</p></div></aside></Transition></main>
</template>

<style lang="scss" scoped>
