iled { color:#b23d45; } .order-row strong { font:500 22px $font-secondary; } .loading,.error { color:#706663; padding:30px 0; } .error { color:#b23d45; } .create-user { align-items:flex-start; gap:8vw; margin-top:80px; padding:45px; background:#2c3430; color:#fffaf6; } .create-user > div,.create-user form { flex:1; } .create-user h2 { margin:14px 0; } .create-user p:not(.eyebrow) { color:#d4c6c0; line-height:1.5; } form { display:flex; flex-direction:column; gap:10px; } input,select { box-sizing:border-box; padding:12px; border:1px solid rgba(255,255,255,.25); color:#fffaf6; background:transparent; font:14px $font-principal; } option { color:#211817; } form button,.whatsapp { border:0; padding:13px; color:#fffaf6; background:#9a4f58; text-decoration:none; font:600 12px $font-principal; cursor:pointer; } form p { margin:0; font-size:12px; } .detail { position:fixed; z-index:20; inset:0 0 0 auto; width:min(440px,100vw); box-sizing:border-box; padding:42px 30px; overflow:auto; background:#fffaf6; box-shadow:-20px 0 60px rgba(33,24,23,.15); } .close { position:absolute; top:18px; right:18px; width:38px; height:38px; border:0; border-radius:50%; background:#eaded7; font-size:25px; cursor:pointer; } .detail h2 { margin:14px 0; } .contact { color:#706663; line-height:1.6; } .whatsapp { display:block; margin:24px 0; text-align:center; background:#427a55; } .detail-block { margin-top:24px; padding-top:20px; border-top:1px solid #e4d7d0; } .detail-block p { display:flex; justify-content:space-between; gap:12px; color:#625551; line-height:1.5; } .detail-block a { color:#9a4f58; font-weight:600; } .detail-block b { display:block; margin-top:14px; } .card { font-family:$font-secondary; font-size:20px; } @media (max-width:700px) { .dashboard { padding:20px 16px 60px; } header p { display:none; } .intro { margin:70px 0 35px; } .metrics,.create-user { flex-direction:column; } .metrics { gap:1px; } .metrics div { width:100%; box-sizing:border-box; min-height:95px; } .create-user { padding:28px 22px; gap:25px; } .create-user > div,.create-user form { width:100%; } .order-row small { max-width:170px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; } }
</style>
